const startConsultation = `-- name: StartConsultation :one
UPDATE consultations
SET
    status     = 'in_progress',
    started_at = NOW(),
    updated_at = NOW()
WHERE id = $1
  AND status = 'accepted'
RETURNING id, symptom_session_id, patient_id, provider_staff_id, clinic_id, channel, requested_at, accepted_at, started_at, ended_at, duration_seconds, status, triage_level_at_start, ended_by, end_reason, consultation_fee, fee_currency, payment_status, payment_reference, patient_rating, patient_feedback, rated_at, follow_up_appointment_id, created_at, updated_at
`

// First message sent — move from accepted → in_progress.
func (q *Queries) StartConsultation(ctx context.Context, id pgtype.UUID) (Consultation, error) {
	row := q.db.QueryRow(ctx, startConsultation, id)
	var i Consultation
	err := row.Scan(
		&i.ID,
		&i.SymptomSessionID,
		&i.PatientID,
		&i.ProviderStaffID,
		&i.ClinicID,
		&i.Channel,
		&i.RequestedAt,
		&i.AcceptedAt,
		&i.StartedAt,
		&i.EndedAt,
		&i.DurationSeconds,
		&i.Status,
		&i.TriageLevelAtStart,
		&i.EndedBy,
		&i.EndReason,
		&i.ConsultationFee,
		&i.FeeCurrency,
		&i.PaymentStatus,
		&i.PaymentReference,
		&i.PatientRating,
		&i.PatientFeedback,
		&i.RatedAt,
		&i.FollowUpAppointmentID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

